    "path": "app/tools/history/page.tsx",
    "content": "import type { Metadata } from \"next\";\nimport { ScoreHistoryWorkspace } from \"@/components/score-workspaces\";\nimport { SiteFooter } from \"@/components/site-footer\";\nimport { SiteHeader } from \"@/components/site-header\";\n\nexport const metadata: Metadata = { title: \"成績歷史紀錄｜全國國中升學資訊網\", alternates: { canonical: \"/tools/history\" }, robots: { index: false, follow: false } };\nexport default function ScoreHistoryPage() { return <main className=\"min-h-screen jshs-page-shell\"><SiteHeader activeHref=\"/tools\" /><ScoreHistoryWorkspace /><SiteFooter /></main>; }\n"
